import type { PreparedTextWithSegments } from '../src/layout.ts'

export type DiagnosticUnit = {
  text: string
  start: number
  end: number
}

const diagnosticGraphemeSegmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' })

export function getDiagnosticUnits(prepared: PreparedTextWithSegments): DiagnosticUnit[] {
  const units: DiagnosticUnit[] = []
  let offset = 0

  for (let i = 0; i < prepared.segments.length; i++) {
    const segment = prepared.segments[i]!
    if (prepared.breakableWidths[i] !== null) {
      let localOffset = 0
      for (const grapheme of diagnosticGraphemeSegmenter.segment(segment)) {
        const start = offset + localOffset
        localOffset += grapheme.segment.length
        units.push({ text: grapheme.segment, start, end: offset + localOffset })
      }
    } else {
      units.push({ text: segment, start: offset, end: offset + segment.length })
    }
    offset += segment.length
  }

  return units
}

export function getLineContent(text: string, end: number): { text: string, end: number } {
  const trimmed = text.trimEnd()
  return {
    text: trimmed,
    end: end - (text.length - trimmed.length),
  }
}

export function formatBreakContext(text: string, breakOffset: number, radius = 32): string {
  const start = Math.max(0, breakOffset - radius)
  const end = Math.min(text.length, breakOffset + radius)
  return `${start > 0 ? '…' : ''}${text.slice(start, breakOffset)}|${text.slice(breakOffset, end)}${end < text.length ? '…' : ''}`
}

export function measureCanvasTextWidth(
  ctx: CanvasRenderingContext2D,
  text: string,
  font: string,
): number {
  ctx.font = font
  return ctx.measureText(text).width
}

export function measureDomTextWidth(
  doc: Document,
  text: string,
  font: string,
  direction: string,
): number {
  const span = doc.createElement('span')
  span.style.position = 'absolute'
  span.style.visibility = 'hidden'
  span.style.whiteSpace = 'pre'
  span.style.font = font
  span.style.direction = direction
  span.style.unicodeBidi = 'plaintext'
  span.textContent = text
  doc.body.appendChild(span)
  const width = span.getBoundingClientRect().width
  doc.body.removeChild(span)
  return width
}

import { createServer as createHttpServer } from 'node:http'
import { getAvailablePort } from './browser-automation.ts'

export async function startPostedReportServer<T extends { requestId?: string }>(expectedRequestId: string): Promise<{
  endpoint: string
  waitForReport: (timeoutMs?: number | null) => Promise<T>
  close: () => void
}> {
  const port = await getAvailablePort()
  let resolveReport: ((report: T) => void) | null = null
  let rejectReport: ((error: Error) => void) | null = null
  const reportPromise = new Promise<T>((resolve, reject) => {
    resolveReport = resolve
    rejectReport = reject
  })

  const server = createHttpServer((req, res) => {
    res.setHeader('access-control-allow-origin', '*')
    if (req.method === 'OPTIONS') {
      res.setHeader('access-control-allow-methods', 'POST, OPTIONS')
      res.statusCode = 204
      res.end()
      return
    }

    if (req.method !== 'POST') {
      res.statusCode = 404
      res.end()
      return
    }

    let body = ''
    req.setEncoding('utf8')
    req.on('data', chunk => {
      body += chunk
    })
    req.on('end', () => {
      try {
        const report = JSON.parse(body) as T
        if (report.requestId === expectedRequestId) {
          resolveReport?.(report)
        }
        res.statusCode = 204
        res.end()
      } catch (error) {
        res.statusCode = 400
        res.end(error instanceof Error ? error.message : String(error))
      }
    })
  })

  await new Promise<void>((resolve, reject) => {
    server.once('error', reject)
    server.listen(port, '127.0.0.1', () => resolve())
  })

  return {
    endpoint: `http://127.0.0.1:${port}/report`,
    async waitForReport(timeoutMs: number | null = 120_000): Promise<T> {
      if (timeoutMs === null) {
        return await reportPromise
      }
      return await new Promise<T>((resolve, reject) => {
        const timer = setTimeout(() => {
          reject(new Error('Timed out waiting for posted report'))
        }, timeoutMs)

        reportPromise.then(
          report => {
            clearTimeout(timer)
            resolve(report)
          },
          error => {
            clearTimeout(timer)
            reject(error)
          },
        )
      })
    },
    close() {
      server.close()
      rejectReport?.(new Error('Report server closed before report arrived'))
    },
  }
}

export type NavigationPhase = 'loading' | 'measuring' | 'posting'

type NavigationPhaseState = {
  phase: NavigationPhase
  requestId?: string
}

function getHashParams(urlOrHash: string): URLSearchParams {
  const hashStart = urlOrHash.indexOf('#')
  const hash = hashStart === -1 ? urlOrHash : urlOrHash.slice(hashStart + 1)
  return new URLSearchParams(hash)
}

export function buildNavigationPhaseHash(phase: NavigationPhase, requestId?: string): string {
  const params = new URLSearchParams()
  params.set('phase', phase)
  if (requestId !== undefined) {
    params.set('requestId', requestId)
  }
  return `#${params.toString()}`
}

export function buildNavigationReportHash(report: unknown): string {
  const params = new URLSearchParams()
  params.set('report', JSON.stringify(report))
  return `#${params.toString()}`
}

export function readNavigationReportText(urlOrHash: string): string {
  return getHashParams(urlOrHash).get('report') ?? ''
}

export function readNavigationPhaseState(urlOrHash: string): NavigationPhaseState | null {
  const params = getHashParams(urlOrHash)
  const phase = params.get('phase')
  if (phase !== 'loading' && phase !== 'measuring' && phase !== 'posting') {
    return null
  }

  const requestId = params.get('requestId') ?? undefined
  return requestId === undefined ? { phase } : { phase, requestId }
}

